const incomingItems = $input.all();
const historyRows = incomingItems
  .map(item => item.json)
  .filter(row => row && !row.error && (row.content || row.created_at || row.timestamp || row.role));

if (historyRows.length === 0) {
  return { json: { formatted_history: [] } };
}

const sorted = historyRows.sort((a, b) => {
  const ta = new Date(a.created_at || a.timestamp || 0).getTime();
  const tb = new Date(b.created_at || b.timestamp || 0).getTime();
  return ta - tb;
});

const formattedHistory = sorted
  .slice(-20)
  .map(msg => ({
    role: msg.role === "assistant" ? "assistant" : "user",
    content: String(msg.content || "")
  }))
  .filter(msg => msg.content.trim() !== "");

return {
  json: {
    formatted_history: formattedHistory
  }
};

const rawUserMsg = String($('Normalize Incoming Message').first().json.userMessage || '');
const userMsg = rawUserMsg.toLowerCase();

// ─── Intent Detection ──────────────────────────────────────────────────────
const intents = {
  price: /harga|biaya|bayar|berapa|paket|membership|member|promo|diskon|trial|pricelist|price list|list harga|tarif|cicil|worth|sebanding|investasi|murah|mahal|kemahalan/.test(userMsg),

  class: /kelas|jadwal|program|class|olahraga|latihan|yoga|strength|pilates|fitdance|boxing|trampoline|aerobic|body combat|power step|cardio|hiit|tabata|abs|core|toning/.test(userMsg),

  coach: /coach|pelatih|trainer|instruktur|pengajar|guru|komunitas|support|siapa yang ngajar|siapa coachnya/.test(userMsg),

  location: /lokasi|alamat|dimana|di mana|maps|google map|parkir|fasilitas|tempat|kepanjen|malang|akses|rute|jalan/.test(userMsg),

  challenge: /21 hari|21 days|challenge|meal plan|nutrisi|diet|meal replacement|program diet|program 21/.test(userMsg),

  goals: /target|goals|turun|naik|berat|langsing|fit|sehat|percaya diri|gemuk|kurus|ideal|diet|bentuk badan|perut|pinggang|obesitas|badan|tubuh|transformasi|program turun/.test(userMsg),

  registration: /daftar|daftarnya|join|gabung|pendaftaran|booking|form|formulir|isi form|cara daftar|gimana daftar|bagaimana daftar|bisa daftar|daftar di sini|daftar disini|minta form|mau coba|pengen coba|cobain dulu|trial gratis|coba dulu/.test(userMsg),

  admin: /admin|nomor admin|kontak admin|wa admin|whatsapp admin|cs admin|hubungi admin|contact|nomornya|nomor wa/.test(userMsg),

  social: /instagram|ig\b|sosmed|sosial media|social media|portfolio|portofolio|gambaran|keseruan|transformasi|foto|ulasan|testimoni|before after|sebelum sesudah|hasilnya|bukti|review/.test(userMsg),

  objection: /mahal|kemahalan|mahal banget|mahal amat|kok mahal|terlalu mahal|harga tinggi|harga mahal|bisa lebih murah|ada yang lebih murah|kurang terjangkau|worth it|worth ga|sebanding ga|sepadan/.test(userMsg),

  about: /stepup itu|tentang stepup|apa itu stepup|cerita dong|ceritain|gimana stepup|profil|sejarah|gym perempuan|gym wanita|ladies gym|khusus wanita|khusus perempuan|bedanya sama gym lain|bedanya apa dengan/.test(userMsg),

  event: /event|acara|lomba|kompetisi|special event|open class|free class|kelas gratis|kelas special/.test(userMsg),
};

// ─── Category Mapping ──────────────────────────────────────────────────────
const categoryMap = {
  price:        ['harga_pembayaran'],
  class:        ['kelas_program'],
  coach:        ['coach_community'],
  location:     ['lokasi_fasilitas'],
  challenge:    ['challenge_21_days', 'harga_pembayaran'],
  goals:        ['goals_transformasi', 'target_member'],
  registration: ['pendaftaran'],
  admin:        ['admin'],
  social:       ['tentang_stepup'],
  objection:    ['harga_pembayaran', 'tentang_stepup'],
  about:        ['tentang_stepup', 'faq_umum'],
  event:        ['tentang_stepup', 'faq_umum'],
};

const defaultCategories = new Set(['tentang_stepup', 'faq_umum']);
const preferredCategories = new Set(defaultCategories);
for (const [intent, active] of Object.entries(intents)) {
  if (active && categoryMap[intent]) categoryMap[intent].forEach(c => preferredCategories.add(c));
}

// ─── Score KB Rows ─────────────────────────────────────────────────────────
const allKb = $('Fetch Knowledge Base').all()
  .map(d => d.json)
  .filter(row => row && (row.description || row.content || row.category || row.intent_name));

const stopWords = new Set(['yang','dan','ini','itu','bisa','mau','ada','untuk','dengan','apa','kak','ya','ga','gak','tidak','mau','kak','kak']);

const keywordParts = [...new Set(
  userMsg
    .replace(/[^a-z0-9\s]/gi, ' ')
    .split(/\s+/)
    .map(s => s.trim())
    .filter(s => s.length >= 3 && !stopWords.has(s))
)];

function scoreRow(row) {
  const cat = String(row.category || '').toLowerCase();
  const intent = String(row.intent_name || '').toLowerCase();
  const text = [row.intent_name, row.description, row.content, row.title, row.category]
    .map(v => String(v || '').toLowerCase())
    .join(' ');

  let score = 0;
  if (preferredCategories.has(cat)) score += 8;
  if (defaultCategories.has(cat)) score += 2;

  for (const kw of keywordParts) {
    if (intent.includes(kw)) score += 6;
    if (cat.includes(kw)) score += 4;
    if (text.includes(kw)) score += 2;
  }

  if (intents.admin     && cat === 'admin')                                           score += 20;
  if (intents.location  && cat === 'lokasi_fasilitas')                                score += 20;
  if (intents.about     && cat === 'tentang_stepup')                                  score += 18;
  if (intents.price     && cat === 'harga_pembayaran')                                score += 15;
  if (intents.objection && cat === 'harga_pembayaran')                                score += 15;
  if (intents.registration && cat === 'pendaftaran')                                  score += 15;
  if (intents.challenge && cat === 'challenge_21_days')                               score += 15;
  if (intents.coach     && cat === 'coach_community')                                 score += 15;
  if (intents.social    && cat === 'tentang_stepup')                                  score += 15;
  if (intents.objection && cat === 'tentang_stepup')                                  score += 10;
  if (intents.about     && cat === 'faq_umum')                                        score += 10;
  if (intents.goals     && (cat === 'goals_transformasi' || cat === 'target_member')) score += 12;
  if (intents.class     && cat === 'kelas_program')                                   score += 12;

  return score;
}

const scoredKb = allKb
  .map(row => ({ row, score: scoreRow(row) }))
  .filter(entry => entry.score > 0)
  .sort((a, b) => b.score - a.score || Number(a.row.id || 0) - Number(b.row.id || 0));

const fallbackKb = allKb
  .filter(row => defaultCategories.has(String(row.category || '').toLowerCase()))
  .slice(0, 8)
  .map(row => ({ row, score: 1 }));

const maxKb = (intents.admin || intents.about) ? 20 : 16;
const finalKb = (scoredKb.length ? scoredKb : fallbackKb)
  .slice(0, maxKb)
  .map(entry => entry.row);

const kbItems = finalKb.map(row => ({ json: { ...row, _source: 'kb' } }));

// ─── Sheet Data ────────────────────────────────────────────────────────────
const sheetItems = [];

// Filter jadwal by hari jika disebutkan
const dayList = ['senin','selasa','rabu','kamis','jumat',"jum'at",'sabtu','minggu'];
const mentionedDay = dayList.find(d => userMsg.includes(d)) || null;

// Harga & Promo
if (intents.price || intents.challenge || intents.objection || intents.registration) {
  const hargaRows = $('Fetch Sheet Harga').all().map(d => d.json).filter(r => {
    if (!r || !r.nama_paket) return false;
    const s = String(r.status || '').toLowerCase();
    return !s || s === 'aktif' || s === 'active';
  });
  for (const row of hargaRows) {
    sheetItems.push({
      json: {
        _source: 'sheet_harga',
        category: 'harga_pembayaran',
        content: [
          `Nama Paket: ${row.nama_paket}`,
          row.kategori        ? `Kategori: ${row.kategori}` : '',
          row.harga           ? `Harga: ${row.harga}` : '',
          row.durasi          ? `Durasi: ${row.durasi}` : '',
          row.fasilitas_utama ? `Fasilitas: ${row.fasilitas_utama}` : '',
          row.ketentuan       ? `Ketentuan: ${row.ketentuan}` : '',
          row.cocok_untuk     ? `Cocok Untuk: ${row.cocok_untuk}` : '',
        ].filter(Boolean).join(' | '),
      }
    });
  }

  const promoRows = $('Fetch Sheet Promo').all().map(d => d.json).filter(r =>
    r && r.nama_promo && String(r.status || '').toLowerCase() === 'active'
  );
  for (const row of promoRows) {
    sheetItems.push({
      json: {
        _source: 'sheet_promo',
        category: 'harga_pembayaran',
        content: [
          `Promo: ${row.nama_promo}`,
          row.diskon ? `Diskon: ${row.diskon}` : '',
          row.harga  ? `Harga Promo: ${row.harga}` : '',
          row.syarat ? `Syarat: ${row.syarat}` : '',
        ].filter(Boolean).join(' | '),
      }
    });
  }
}

// Jadwal (filter by hari jika ada)
if (intents.class) {
  let rows = $('Fetch Sheet Jadwal').all().map(d => d.json).filter(r => r && (r.nama_kelas || r.kelas));
  if (mentionedDay) {
    const filtered = rows.filter(r => String(r.hari || '').toLowerCase().includes(mentionedDay));
    if (filtered.length > 0) rows = filtered;
  }
  for (const row of rows) {
    sheetItems.push({
      json: {
        _source: 'sheet_jadwal',
        category: 'kelas_program',
        content: [
          `Kelas: ${row.nama_kelas || row.kelas || ''}`,
          row.hari  ? `Hari: ${row.hari}` : '',
          row.jam   ? `Jam: ${row.jam}` : '',
          row.coach ? `Coach: ${row.coach}` : '',
        ].filter(Boolean).join(' | ')
      }
    });
  }
}

// Coach
if (intents.coach) {
  const rows = $('Fetch Sheet Coach').all().map(d => d.json).filter(r => r && r.nama_coach);
  for (const row of rows) {
    sheetItems.push({
      json: {
        _source: 'sheet_coach',
        category: 'coach_community',
        content: [
          `Coach: ${row.nama_coach}`,
          row.specialist    ? `Specialist: ${row.specialist}` : '',
          row.hari_mengajar ? `Mengajar: ${row.hari_mengajar}` : '',
          row.bio           ? `Bio: ${row.bio}` : '',
        ].filter(Boolean).join(' | ')
      }
    });
  }
}

// Event & Challenge
if (intents.challenge || intents.event || intents.goals) {
  const rows = $('Fetch Sheet Event').all().map(d => d.json).filter(r => {
    if (!r) return false;
    const s = String(r.status || '').toLowerCase();
    return !s || s === 'aktif' || s === 'active';
  });
  for (const row of rows) {
    sheetItems.push({
      json: {
        _source: 'sheet_event',
        category: 'challenge_21_days',
        content: [
          (row.nama_event || row.nama_program) ? `Event: ${row.nama_event || row.nama_program}` : '',
          row.deskripsi ? `Deskripsi: ${row.deskripsi}` : '',
          row.harga     ? `Harga: ${row.harga}` : '',
          row.durasi    ? `Durasi: ${row.durasi}` : '',
          row.fasilitas ? `Fasilitas: ${row.fasilitas}` : '',
        ].filter(Boolean).join(' | ')
      }
    });
  }
}

return [...sheetItems, ...kbItems];

function safeGet(nodeName) {
  try {
    return $(nodeName).all().map(d => d.json).filter(row => row && !row.error && Object.keys(row).length > 0);
  } catch (e) { return []; }
}

const rawUserMsg = String($('Normalize Incoming Message').first().json.userMessage || '');
const userMsg = rawUserMsg.toLowerCase();

const nowJkt = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const dayNames = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const currentDayName = dayNames[nowJkt.getDay()];
const currentHour = nowJkt.getHours();
const currentTimeStr = nowJkt.toTimeString().slice(0,5) + ' WIB';
const greetingTime = currentHour < 11 ? 'pagi' : currentHour < 15 ? 'siang' : currentHour < 18 ? 'sore' : 'malam';

const resolvedUserMsg = userMsg
  .replace(/\bhari ini\b/g, currentDayName.toLowerCase())
  .replace(/\bsekarang\b(?=.*jadwal)/g, currentDayName.toLowerCase());

const mentionsToday = /hari ini|sekarang|today/.test(userMsg);

function isActive(row) {
  const s = String(row.status || row.Status || '').toLowerCase();
  return !s || s === 'aktif' || s === 'active';
}

// Dipindah ke atas karena dipakai di scoreHargaRow
function rupiahNumber(v) { const n = Number(String(v||'').replace(/\D/g,'')); return isFinite(n) && n > 0 ? n : null; }
function rupiahFormat(n) { return 'Rp' + Number(n).toLocaleString('id-ID'); }

const allHarga    = safeGet('Fetch Sheet Harga').filter(isActive);
const allJadwal   = safeGet('Fetch Sheet Jadwal').filter(isActive);
const allCoachRaw = safeGet('Fetch Sheet Coach').filter(isActive);

// ─── Intent Flags (synced dengan Filter KB By Intent) ─────────────────────
const isPureGreeting = /^(halo|hallo|hello|hi|hey|pagi|siang|sore|malam|assalamualaikum|wa'alaikum|waalaikum|selamat pagi|selamat siang|selamat sore|selamat malam|hai|hei|hoi|oi|assalam|waalaikumsalam|السلام|permisi|excuse me)[\s!.,]*$/i.test(rawUserMsg.trim());
const hasGreetingPrefix = /^(halo|hallo|hello|hi|hey|hai|hei|selamat pagi|selamat siang|selamat sore|selamat malam|assalamualaikum|permisi)[\s,!.]*/i.test(rawUserMsg.trim());
const wantsFullList    = /semua|lengkap|full|list|daftar lengkap|jadwal lengkap|paket lengkap|pricelist|price list|list harga/.test(userMsg);

const asksLocation    = /alamat|lokasi|dimana|di mana|maps|google map|tempatnya|parkir|akses|rute|jalan ke/.test(userMsg);
const asksAdmin       = /admin|nomor admin|kontak admin|wa admin|whatsapp admin|cs admin|hubungi admin|contact|nomornya|nomor wa|wa-nya/.test(userMsg);
const asksSocialMedia = /instagram|ig\b|sosmed|sosial media|social media|portfolio|portofolio|gambaran|keseruan|transformasi|foto|ulasan|testimoni|before after|sebelum sesudah|hasilnya|bukti|review/.test(userMsg);

const hasNumericPriceMention = /(\d+\s*(k|rb|ribu|jt|juta)\b|\b\d{4,9}\b)/.test(userMsg);
const asksPrice    = /harga|biaya|berapa|paket|member|membership|promo|diskon|trial|free|pricelist|price list|list harga|tarif|cicil|worth|sepadan|sebanding/.test(userMsg) || hasNumericPriceMention;
const asksObjection = /mahal|kemahalan|mahal banget|mahal amat|kok mahal|terlalu mahal|harga tinggi|harga mahal|bisa lebih murah|ada yang lebih murah|kurang terjangkau|worth it|worth ga|sebanding ga|sepadan/.test(userMsg);

const asksSchedule = /jadwal|jam|hari|kapan|senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu/.test(userMsg);
const asksCoach    = /coach|pelatih|trainer|instruktur|pengajar|guru/.test(userMsg);
const asksEvent    = /event|acara|challenge|open class|free class|kelas gratis|kelas special|lomba|kompetisi/.test(userMsg);
const asksPromo    = /promo|diskon|trial/.test(userMsg);
const asksAbout    = /stepup itu|tentang stepup|apa itu stepup|cerita dong|ceritain|gimana stepup|profil|sejarah|gym perempuan|gym wanita|ladies gym|khusus wanita|khusus perempuan|bedanya sama gym lain/.test(userMsg);

const hasSpecificDay = /senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu/.test(resolvedUserMsg) || mentionsToday;

const jadwalClassNames = [...new Set(allJadwal.map(r => String(r.kelas || '').toLowerCase()).filter(Boolean))];
const mentionedClass   = jadwalClassNames.find(cls => userMsg.includes(cls));
const asksClass        = !!mentionedClass || /kelas|class/.test(userMsg);

// ─── Rupiah helpers ────────────────────────────────────────────────────────
function normalizeRupiahMentions(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/(\d+)\s*jt\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*juta\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*rb\b/g, (_, n) => String(Number(n) * 1000))
    .replace(/(\d+)\s*ribu\b/g, (_, n) => String(Number(n) * 1000))
    .replace(/(\d+)\s*k\b/g, (_, n) => String(Number(n) * 1000));
}

function extractMentionedPrices(text) {
  const normalized = normalizeRupiahMentions(text);
  return [...new Set((normalized.match(/\d{4,9}/g) || [])
    .map(value => Number(value))
    .filter(value => Number.isFinite(value) && value > 0))];
}

function packageTokens(name) {
  return String(name || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(token => token.length >= 4 && !['days', 'challenge', 'program', 'paket', 'class', 'hari', 'fit'].includes(token));
}

function scoreHargaRow(row, msg, mentionedPrices) {
  const fullName = String(row.nama_paket || '').toLowerCase();
  if (!fullName) return 0;
  let score = 0;
  if (msg.includes(fullName)) score += 100;
  const rowPrice = rupiahNumber(row.harga);
  if (rowPrice && mentionedPrices.includes(rowPrice)) score += 80;
  const tokens = packageTokens(fullName);
  const matchedTokens = tokens.filter(token => msg.includes(token));
  score += matchedTokens.length * 10;
  if (tokens.length > 0 && matchedTokens.length === tokens.length) score += 25;
  if (/challenge/.test(msg) && /challenge/.test(fullName)) score += 8;
  if (/private/.test(msg)   && /private/.test(fullName))   score += 8;
  if (/vip/.test(msg)       && /vip/.test(fullName))       score += 8;
  if (/reguler/.test(msg)   && /reguler/.test(fullName))   score += 8;
  return score;
}

// ─── Match harga rows ──────────────────────────────────────────────────────
const mentionedPrices  = extractMentionedPrices(userMsg);
const asksDifference   = /apa bedanya|bedanya apa|beda apa|beda nya|perbedaannya|perbedaan|compare|bandingkan|vs\b|versus/.test(userMsg);
const matchedHargaRows = (asksPrice || asksObjection)
  ? allHarga
      .map(row => ({ row, score: scoreHargaRow(row, userMsg, mentionedPrices) }))
      .filter(entry => entry.score > 0)
      .sort((a, b) => b.score - a.score || (rupiahNumber(a.row.harga) || 0) - (rupiahNumber(b.row.harga) || 0))
      .map(entry => entry.row)
  : [];

const packageNames     = [...new Set(allHarga.map(r => String(r.nama_paket || '').toLowerCase()).filter(Boolean))];
const mentionedPackage = matchedHargaRows[0]
  ? String(matchedHargaRows[0].nama_paket || '').toLowerCase()
  : (packageNames.find(pkg => userMsg.includes(pkg)) || null);

const asksClassAndPrice    = (asksClass || !!mentionedClass) && asksPrice;
const asksOnlyGeneralPrice = asksPrice && !mentionedPackage && matchedHargaRows.length === 0 && !/(private|vip|challenge|21 hari|bulanan|bulan|harian|perdatang|trial|special|online|pengelolaan|berat badan|turbo|reguler|boxing|yoga|pilates|trampoline|quick start)/.test(userMsg);

// ─── Answer Mode Routing ───────────────────────────────────────────────────
let answerMode = 'GENERAL';
if (asksAdmin)                              answerMode = 'ADMIN_INFO';
else if (asksLocation)                      answerMode = 'LOCATION';
else if (asksSocialMedia)                   answerMode = 'SOCIAL_MEDIA';
else if (asksClassAndPrice)                 answerMode = 'CLASS_AND_PRICE';
else if (asksPrice && asksOnlyGeneralPrice) answerMode = 'PRICE_GENERAL_CLARIFY';
else if (asksPrice)                         answerMode = 'PRICE_SPECIFIC';
else if (asksObjection)                     answerMode = 'PRICE_OBJECTION';
else if (asksSchedule && hasSpecificDay)    answerMode = 'SCHEDULE_SPECIFIC_DAY';
else if (asksSchedule)                      answerMode = 'SCHEDULE_GENERAL';
else if (asksCoach)                         answerMode = 'COACH_INFO';
else if (asksClass)                         answerMode = 'CLASS_GENERAL';
else if (asksEvent || asksPromo)            answerMode = 'EVENT_PROMO';
else if (asksAbout)                         answerMode = 'ABOUT_STEPUP';

// ─── Utility functions ─────────────────────────────────────────────────────
function compactRow(row, keys) {
  return keys.map(k => row[k] ? `${k}: ${row[k]}` : '').filter(Boolean).join(' | ');
}
function formatRows(rows, keys) {
  return rows.filter(isActive).map(r => compactRow(r, keys)).filter(Boolean).join('\n');
}
function unique(rows, key) {
  return [...new Set(rows.map(r => String(r[key] || '').trim()).filter(Boolean))];
}

// ─── KB processing ─────────────────────────────────────────────────────────
let kb = safeGet('Filter KB By Intent').filter(r => !r._source || r._source === 'kb');

if (asksLocation) {
  const locKb = kb.filter(r => {
    const intent = String(r.intent_name||'').toLowerCase();
    const cat    = String(r.category||'').toLowerCase();
    const txt    = String(r.description||r.content||'').toLowerCase();
    return cat === 'lokasi_fasilitas' || intent.includes('alamat') || txt.includes('alamat lengkap');
  });
  kb = [...locKb, ...kb.filter(r => !locKb.some(l => l.id === r.id))];
}

if (asksSocialMedia) {
  const socialRe = /instagram|portfolio|portofolio|gambaran|keseruan|transformasi|sosial|social|ulasan|testimoni/i;
  const socialKb = kb.filter(r => socialRe.test(String(r.intent_name||'') + ' ' + String(r.description||r.content||'')));
  kb = [...socialKb, ...kb.filter(r => !socialKb.includes(r))];
}

kb = kb.slice(0, wantsFullList || asksOnlyGeneralPrice ? 20 : (asksAdmin ? 10 : 8));

// ─── Data fetching ─────────────────────────────────────────────────────────
const promo = (asksPromo || asksPrice || asksObjection)
  ? safeGet('Fetch Sheet Promo').filter(isActive).slice(0, 5) : [];

const harga = (asksPrice || asksObjection)
  ? (matchedHargaRows.length > 0 ? matchedHargaRows : allHarga)
  : [];

// Jadwal dengan filter hari
let jadwalToShow   = allJadwal;
let filteringDebug = { searched: null, found: null, error: null };

if (hasSpecificDay) {
  const dayRegex = /senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu/i;
  const dayMatch = (resolvedUserMsg || userMsg).match(dayRegex);
  if (dayMatch) {
    const targetDay = dayMatch[0].toLowerCase().replace(/jum'at/i, 'jumat');
    filteringDebug.searched = targetDay;
    const filtered = allJadwal.filter(r => String(r.hari || '').trim().toLowerCase() === targetDay);
    filteringDebug.found = filtered.length;
    if (filtered.length === 0) {
      const availableDays = [...new Set(allJadwal.map(r => String(r.hari || '').trim()))];
      filteringDebug.error = `No schedule for "${targetDay}". Available: ${availableDays.join(', ')}`;
    } else {
      jadwalToShow = filtered;
    }
  }
}

// Coach dengan filter specialist
let coachToShow = allCoachRaw;
if (asksCoach) {
  const classKeyword = allCoachRaw
    .flatMap(c => (c.specialist||'').split(',').map(s => s.trim()))
    .find(cls => cls && userMsg.includes(cls.toLowerCase()));
  if (classKeyword) {
    const filtered = allCoachRaw.filter(c => String(c.specialist||'').toLowerCase().includes(classKeyword.toLowerCase()));
    if (filtered.length > 0) coachToShow = filtered;
  }
}

const coach = asksCoach ? coachToShow : [];
const event = (asksEvent || asksPromo) ? safeGet('Fetch Sheet Event').filter(isActive).slice(0, 5) : [];

// Enrich jadwal dengan specialist coach
const coachMap = {};
allCoachRaw.forEach(c => {
  const name = String(c.nama_coach || '').trim().toLowerCase();
  if (name) coachMap[name] = c;
});

const jadwalJoined = jadwalToShow.map(j => {
  const coachName = String(j.coach || '').trim();
  const coachData = coachMap[coachName.toLowerCase()];
  if (coachData && coachData.specialist) {
    return { ...j, coach: `${coachName} [${coachData.specialist}]` };
  }
  return j;
});

const jadwal = (asksSchedule || asksClass) ? jadwalJoined.slice(0, wantsFullList ? 50 : 30) : [];

// ─── Summary data ──────────────────────────────────────────────────────────
const classNames      = unique(allJadwal, 'kelas');
const priceCategories = unique(allHarga, 'kategori');
const numericPrices   = allHarga.map(r => rupiahNumber(r.harga)).filter(Boolean);
const minPrice        = numericPrices.length ? Math.min(...numericPrices) : null;
const maxPrice        = numericPrices.length ? Math.max(...numericPrices) : null;
const priceRangeText  = minPrice && maxPrice ? `${rupiahFormat(minPrice)} sampai ${rupiahFormat(maxPrice)}` : '';

const locationText = asksLocation
  ? kb.map(r => r.description||r.content||'').find(t => /alamat lengkap|Jl\.|Kepanjen|Malang/i.test(t)) || '' : '';
const adminText    = asksAdmin
  ? kb.map(r => r.description||r.content||'').find(t => /admin\s*1|088|085|082|081/i.test(t)) || '' : '';
const socialText   = asksSocialMedia
  ? kb.map(r => r.description||r.content||'').find(t => /instagram\.com|portofolio|portfolio/i.test(t)) || '' : '';
const kbText       = kb.map(r => r.description||r.content||'').filter(Boolean).join('\n');

// ─── Build dataContext ─────────────────────────────────────────────────────
const parts = [];
parts.push(`=== WAKTU SEKARANG ===\nHari: ${currentDayName}\nJam: ${currentTimeStr}\nSapaan: selamat ${greetingTime}`);

if (classNames.length)      parts.push(`=== RINGKASAN NAMA KELAS ===\n${classNames.join(', ')}`);
if (priceCategories.length) parts.push(`=== KATEGORI HARGA TERSEDIA ===\n${priceCategories.join(', ')}`);
if (locationText)           parts.push(`=== ALAMAT STEPUP ===\n${locationText}`);
if (adminText)              parts.push(`=== KONTAK ADMIN ===\n${adminText}`);
if (socialText)             parts.push(`=== INSTAGRAM & PORTFOLIO ===\n${socialText}`);
if (kbText)                 parts.push(`=== KNOWLEDGE BASE ===\n${kbText}`);
if (promo.length)  parts.push(`=== PROMO AKTIF ===\n${formatRows(promo,  ['nama_promo','deskripsi_promo','harga','benefit','periode'])}`);
if (harga.length)  parts.push(`=== HARGA & PAKET ===\n${formatRows(harga, ['nama_paket','kategori','harga','durasi','fasilitas_utama','ketentuan','cocok_untuk'])}`);
if (jadwal.length) parts.push(`=== JADWAL/KELAS ===\n${formatRows(jadwal, ['hari','jam','kelas','coach'])}`);
if (coach.length)  parts.push(`=== DATA COACH ===\n${formatRows(coach,  ['nama_coach','specialist','hari_mengajar'])}`);
if (event.length)  parts.push(`=== EVENT ===\n${formatRows(event,  ['nama_event','deskripsi','tanggal','harga','lokasi'])}`);

// PRICE_OBJECTION: paksa sertakan harga meski user tidak sebut nama paket
if (answerMode === 'PRICE_OBJECTION' && allHarga.length > 0) {
  const hasHargaBlock = parts.some(p => p.includes('=== HARGA & PAKET ==='));
  if (!hasHargaBlock) {
    const objLines = allHarga.map(r =>
      `• ${r.nama_paket}: ${r.harga ? rupiahFormat(rupiahNumber(r.harga)) : '-'} (${r.durasi || '-'})`
    ).join('\n');
    parts.push(`=== HARGA & PAKET ===\n${objLines}`);
  }
}

const msg = $('Normalize Incoming Message').first().json;

return { json: {
  dataContext: parts.join('\n\n') || 'Tidak ada data referensi.',
  answerMode: isPureGreeting ? 'GREETING' : answerMode,
  locationText, priceRangeText, adminText, socialText, hasSpecificDay,
  asksOnlyGeneralPrice, asksClassAndPrice,
  isPureGreeting, hasGreetingPrefix, currentDayName, greetingTime,
  chat_id: msg.chat_id, whatsapp_number: msg.whatsapp_number,
  client_id: msg.client_id, session_name: msg.session_name,
  timestamp: msg.timestamp, userMessage: rawUserMsg,
  resolvedUserMessage: isPureGreeting ? rawUserMsg : resolvedUserMsg,
  filteringDebug,
  jadwalFilteredCount: jadwal.length,
  coachCount: coach.length,
  answerModeDetermined: answerMode
}};

const assembled = $('Assemble Answer Facts').first().json || {};
const refData = $('Collect Reference Data (Sequential)').first().json || {};
const formattedHistory = $('Format History').first().json.formatted_history || [];
const _rawIncoming = $('Normalize Incoming Message').first().json || {};

const answerFacts = assembled.answer_facts || {};
const primaryFactType = String(assembled.primary_fact_type || 'general');
const primaryFactPayload = assembled.primary_fact_payload || null;
const fallbackFactPayload = assembled.fallback_fact_payload || {};

const userMessage =
  answerFacts.userMessage ||
  refData.resolvedUserMessage ||
  _rawIncoming.userMessage ||
  '';

const answerMode = answerFacts.answerMode || refData.answerMode || 'GENERAL';
const locationText = answerFacts.locationText || refData.locationText || '';
const priceRangeText = answerFacts.priceRangeText || refData.priceRangeText || '';
const socialText = answerFacts.socialText || refData.socialText || '';
const adminText = answerFacts.adminText || refData.adminText || '';
const classDetail = answerFacts.class_detail || null;
const classDetailFound = !!answerFacts.class_detail_found;

const rawUserText = String(userMessage || '').trim();

const hasGreetingPrefix =
  !!refData.hasGreetingPrefix ||
  /^(halo|hallo|hello|hi|hey|hai|hei|assalamualaikum|permisi|selamat pagi|selamat siang|selamat sore|selamat malam|pagi|siang|sore|malam)[\s,!.]*/i.test(rawUserText);

const forbidDecorativeOutput = ['SOCIAL_MEDIA', 'WEIGHT_EXPECTATION'].includes(answerMode);

function detectUserGreetingStyle(text) {
  if (/assalamualaikum/i.test(text)) return 'waalaikumsalam kak';
  if (/selamat pagi/i.test(text)) return 'selamat pagi kak';
  if (/selamat siang/i.test(text)) return 'selamat siang kak';
  if (/selamat sore/i.test(text)) return 'selamat sore kak';
  if (/selamat malam/i.test(text)) return 'selamat malam kak';
  if (/\bpagi\b/i.test(text)) return 'pagi kak';
  if (/\bsiang\b/i.test(text)) return 'siang kak';
  if (/\bsore\b/i.test(text)) return 'sore kak';
  if (/\bmalam\b/i.test(text)) return 'malam kak';
  if (/halo|hallo|hello|hi|hey|hai|hei/i.test(text)) return 'hai kak';
  return '';
}

const preferredGreeting = detectUserGreetingStyle(rawUserText);

function pushPart(parts, title, value) {
  const text = String(value || '').trim();
  if (!text) return;
  parts.push(`=== ${title} ===\n${text}`);
}

const contextParts = [];

pushPart(
  contextParts,
  'WAKTU SEKARANG',
  `Hari: ${refData.currentDayName || '-'}\nSapaan: ${refData.greetingTime ? 'selamat ' + refData.greetingTime : '-'}`
);

if (primaryFactType === 'class_detail' && classDetailFound && classDetail) {
  const classLines = [
    classDetail.nama_olahraga ? `Nama Olahraga: ${classDetail.nama_olahraga}` : '',
    classDetail.alias ? `Alias: ${classDetail.alias}` : '',
    classDetail.deskripsi_singkat ? `Deskripsi Singkat: ${classDetail.deskripsi_singkat}` : '',
    classDetail.manfaat ? `Manfaat: ${classDetail.manfaat}` : '',
    classDetail.cocok_untuk ? `Cocok Untuk: ${classDetail.cocok_untuk}` : '',
    classDetail.level ? `Level: ${classDetail.level}` : '',
    classDetail.fokus_latihan ? `Fokus Latihan: ${classDetail.fokus_latihan}` : '',
    classDetail.status ? `Status: ${classDetail.status}` : ''
  ].filter(Boolean).join('\n');

  pushPart(contextParts, 'DETAIL OLAHRAGA TERPILIH', classLines);
}

if (primaryFactType === 'location' && locationText) {
  pushPart(contextParts, 'ALAMAT STEPUP', locationText);
}

if (primaryFactType === 'admin' && adminText) {
  pushPart(contextParts, 'KONTAK ADMIN', adminText);
}

if (primaryFactType === 'social_media' && socialText) {
  pushPart(contextParts, 'INSTAGRAM & PORTFOLIO', socialText);
}

if (primaryFactType === 'price' && priceRangeText) {
  pushPart(contextParts, 'RENTANG HARGA', priceRangeText);
}

if (primaryFactType !== 'class_detail' && refData.dataContext) {
  const trimmedBaseContext = String(refData.dataContext || '').trim();
  if (trimmedBaseContext) {
    pushPart(contextParts, 'DATA REFERENSI TAMBAHAN', trimmedBaseContext);
  }
}

if (primaryFactType === 'class_detail' && refData.dataContext) {
  const minimalFallback = [
    fallbackFactPayload.locationText ? `Alamat: ${fallbackFactPayload.locationText}` : '',
    fallbackFactPayload.adminText ? `Kontak admin: ${fallbackFactPayload.adminText}` : '',
    fallbackFactPayload.socialText ? `Instagram: ${fallbackFactPayload.socialText}` : ''
  ].filter(Boolean).join('\n');
  if (minimalFallback) {
    pushPart(contextParts, 'REFERENSI PELENGKAP', minimalFallback);
  }
}

const dataContext = contextParts.join('\n\n').trim() || 'Tidak ada data referensi.';

const systemPrompt = `Kamu CS WhatsApp StepUp Ladies Gym.

SUMBER KEBENARAN SATU-SATUNYA HANYA DATA DI BAWAH INI. JANGAN PAKAI PENGETAHUAN UMUM, JANGAN NEBAK, JANGAN MENGARANG.
Kalau info yang diminta user tidak tertulis jelas di data, jawab jujur singkat bahwa datanya belum ada atau belum disebut.
Kalau user menanyakan hal di luar konteks StepUp atau di luar data, arahkan balik dengan sopan tanpa menambah fakta baru.

${dataContext}

Aturan utama:
- Output hanya isi pesan WhatsApp final plain text.
- Jangan sebut database, sistem, AI, prompt, mode, atau proses internal.
- Jangan pakai markdown.
- Jangan ulang pertanyaan user mentah-mentah.
- Jangan menambah nama kelas, harga, coach, promo, jadwal, alamat, nomor admin, fasilitas, link, atau akun yang tidak tertulis di data.
- StepUp TIDAK punya kelas Zumba. Jangan pernah menulis Zumba.
- Jika data tidak cukup, bilang singkat dan jujur.
- Prioritaskan data sheet/ref yang spesifik daripada kalimat promosi umum.
- Jika ada detail harga, jadwal, alamat, nomor admin, atau link sosial di data, salin inti faktanya dengan akurat.

Gaya bicara:
- Natural, sopan, hangat, dan terasa seperti admin WA manusia.
- Jangan kaku, jangan terlalu formal, jangan seperti brosur.
- Boleh pakai kalimat seperti "Malam kak", "Ada nih kak", "Boleh kak", "Yang available sekarang...", "Kalau buat..." secukupnya.
- Hindari pembuka yang datar seperti "Berikut beberapa pilihan paket yang tersedia" kalau bisa dibuat lebih natural.

Aturan greeting yang sangat penting:
- Jika user menyapa, pakai MAKSIMAL SATU sapaan di awal balasan.
- Jangan pernah membuat sapaan ganda seperti "Siang kak, selamat siang", "Pagi kak, selamat pagi", atau "Hai kak, selamat siang".
- Jika user sudah menyebut waktu seperti "selamat pagi/siang/sore/malam", balas dengan SATU bentuk saja yang paling natural, jangan diulang dalam bentuk lain.
- Jika user hanya bilang "halo/hai/hi", boleh balas dengan satu sapaan singkat saja.
- Jika user tidak menyapa, jangan tambahkan greeting atau salam di awal.

Preferensi sapaan untuk pesan ini:
- Ada sapaan di awal user: ${hasGreetingPrefix ? 'ya' : 'tidak'}
- Bentuk sapaan yang paling aman jika memang perlu dipakai: ${preferredGreeting || '(tidak perlu sapaan tambahan)'}

Prioritas fakta untuk pesan ini:
- Tipe fakta utama: ${primaryFactType}
- Jika ada detail olahraga terpilih, utamakan itu dan jangan tenggelamkan dengan daftar data lain yang tidak relevan.
- Jika mode LOCATION, fokus ke alamat.
- Jika mode ADMIN_INFO, fokus ke nomor admin.
- Jika mode SOCIAL_MEDIA, fokus ke link sosial.
- Jika mode harga, fokus ke data harga yang relevan.
- Jika data utama tidak ada, baru gunakan referensi pelengkap seperlunya.

Mode aktif: ${answerMode}
- GREETING: balas sapaan hangat sesuai konteks, 1-2 kalimat. Gunakan hanya satu sapaan.
- LOCATION: jawab alamat langsung dari data alamat yang ada.
- ADMIN_INFO: jika user tanya nomor admin atau kontak admin, jawab langsung semua nomor admin yang ada di data dengan rapi.
- SOCIAL_MEDIA: jawab langsung dengan link Instagram dari data INSTAGRAM & PORTFOLIO persis apa adanya. Jangan tulis URL lain. Jangan bilang datanya belum ada jika link Instagram sudah tersedia di data.
- WEIGHT_EXPECTATION: jika user bertanya soal estimasi turun/naik berat badan, kg per minggu, kg per bulan, atau kapan target ideal tercapai, jawab bahwa hasil tiap individu berbeda-beda dan tidak bisa ditetapkan secara pasti.
- PRICE_GENERAL_CLARIFY: jika user tanya harga secara umum, tampilkan semua paket aktif dari data HARGA & PAKET tanpa dipotong, bukan cuma rentang harga dan bukan cuma sebagian paket. Sertakan nama paket, harga, dan durasi. Jika ada fasilitas_utama boleh tambahkan singkat. Tutup dengan penjelasan singkat bahwa fasilitas dan ketentuan berlaku menyesuaikan paket yang dipilih.
- PRICE_SPECIFIC: jawab hanya paket atau harga yang memang relevan dari data.
- CLASS_GENERAL: tampilkan semua nama kelas yang memang ada pada data.
- CLASS_AND_PRICE: gabungkan kelas yang tersedia dengan info harga yang benar dari data.
- SCHEDULE_SPECIFIC_DAY: tampilkan jadwal untuk hari yang diminta saja.
- COACH_INFO: jawab info coach dari data yang ada.
- EVENT_PROMO: jawab promo, event, atau challenge hanya dari data yang tersedia.
- GENERAL: jawab singkat dan tetap berdasarkan data yang ada.

Aturan wajib:
0. Jika user membuka dengan sapaan lalu lanjut bertanya, balas dengan satu sapaan singkat saja lalu langsung jawab inti pertanyaannya.
1. Jika user tidak menyapa, jangan tambahkan greeting atau salam di awal.
2. Plain text WA saja.
3. CLASS_GENERAL wajib lengkap sesuai data yang tersedia.
4. PRICE_GENERAL_CLARIFY wajib tampilkan semua paket aktif jika data harga tersedia, walaupun user tidak menulis kata pricelist.
5. ADMIN_INFO wajib tampilkan nomor admin dari data jika ada.
6. Jika draft berisi daftar harga atau pricelist, jangan dipotong, jangan diringkas, dan tampilkan semua item yang ada.
7. Jangan pakai CTA robot seperti "silakan tanya", "kami siap membantu".
8. [INTENT:JOIN] hanya kalau user eksplisit mau daftar atau booking sekarang.
9. Kalau data tidak ada, bilang jujur dan singkat.
10. Jangan keluar dari konteks data.
11. Untuk SOCIAL_MEDIA, wajib tampilkan link Instagram persis dari data, jangan disingkat atau diubah.
12. Untuk WEIGHT_EXPECTATION, jangan memberi angka pasti kg per minggu, kg per bulan, atau estimasi waktu pasti.
13. Untuk SOCIAL_MEDIA dan WEIGHT_EXPECTATION, jangan pakai emoji, simbol dekoratif, markdown, atau icon apapun.
14. Jika mode SOCIAL_MEDIA aktif dan link Instagram tersedia di data, prioritaskan jawab langsung link tersebut secara singkat.
15. Jika mode WEIGHT_EXPECTATION aktif, jangan alihkan jawaban ke harga paket, promo, atau jadwal kecuali user memang menanyakannya juga.
16. Jika user menulis "selamat pagi/siang/sore/malam", JANGAN ubah menjadi dua sapaan. Pilih satu saja.
17. Dilarang menggabungkan dua bentuk sapaan dalam satu pembuka.`;

const messages = [
  { role: 'system', content: systemPrompt },
  ...formattedHistory,
  { role: 'user', content: userMessage }
];

const llmPrompt = messages
  .map((msg) => `${String(msg.role || 'user').toUpperCase()}: ${String(msg.content || '').trim()}`)
  .filter(Boolean)
  .join('\n\n');

return {
  json: {
    messages,
    llmPrompt,
    dataContext,
    answerMode,
    locationText,
    priceRangeText,
    socialText,
    adminText,
    hasGreetingPrefix,
    preferredGreeting,
    forbidDecorativeOutput,
    primaryFactType,
    primaryFactPayload,
    classDetailFound,
    classDetail,
    hasSpecificDay: answerFacts.hasSpecificDay ?? refData.hasSpecificDay,
    asksOnlyGeneralPrice: answerFacts.asksOnlyGeneralPrice ?? refData.asksOnlyGeneralPrice,
    asksClassAndPrice: answerFacts.asksClassAndPrice ?? refData.asksClassAndPrice,
    chat_id: _rawIncoming.chat_id,
    whatsapp_number: _rawIncoming.whatsapp_number,
    client_id: _rawIncoming.client_id,
    session_name: _rawIncoming.session_name,
    timestamp: _rawIncoming.timestamp,
    userMessage,
    lead_id: $('Check Lead State').first().json.lead_id
  }
};

const item = $input.first().json;

const ctx = $('Build Human WhatsApp Context').first().json;
const answerMode = String(ctx.answerMode || 'GENERAL');

function getFallbackByMode(mode) {
  const adminRedirect = 'bisa langsung tanya ke admin ya kak 😊';
  if (mode === 'PRICE_GENERAL_CLARIFY' || mode === 'PRICE_SPECIFIC' || mode === 'PRICE_OBJECTION') {
    return 'Untuk info harga dan paket lengkapnya ' + adminRedirect;
  }
  if (mode === 'SCHEDULE_SPECIFIC_DAY' || mode === 'SCHEDULE_GENERAL') {
    return 'Untuk jadwal terbaru ' + adminRedirect;
  }
  if (mode === 'COACH_INFO') {
    return 'Info coach lengkapnya ' + adminRedirect;
  }
  if (mode === 'EVENT_PROMO') {
    return 'Untuk info promo dan event terbaru ' + adminRedirect;
  }
  if (mode === 'LOCATION') {
    return 'Untuk info lokasi lengkapnya ' + adminRedirect;
  }
  if (mode === 'ADMIN_INFO') {
    return 'Untuk kontak admin ' + adminRedirect;
  }
  return 'Boleh kak, cerita kebutuhannya gimana? Biar kami bantu arahkan yang paling cocok 😊';
}

const fallbackReply = getFallbackByMode(answerMode);

const rawReply = String(
  item.output?.[0]?.content?.[0]?.text ||
  item.text ||
  item.message?.content ||
  item.response?.text ||
  item.draftReply ||
  ''
).trim();

function humanClean(text) {
  let out = String(text || '')
    .replace(/\[INTENT:JOIN\]/g, ' [INTENT:JOIN] ')
    .replace(/^#{1,6}\s*/gm, '')
    .replace(/\*\*(.*?)\*\*/g, '*$1*')
    .replace(/__(.*?)__/g, '$1')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const bannedCta = /kami\s+siap\s+membantu\s*[!.]*\s*$|beritahu\s+kami\s+ya\s*[!.]*\s*$|jangan\s+ragu\s+untuk\s+(tanya|menghubungi)|feel\s+free\s+to/i;
  out = out
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !bannedCta.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return out;
}

function classifyJoinIntent(userText, modelText) {
  const msg = String(userText || '').toLowerCase().trim();
  const modelMarkedJoin = String(modelText || '').includes('[INTENT:JOIN]');

  const registrationPhrases = /(cara daftar|gimana daftar|bagaimana daftar|daftarnya gimana|daftarnya bagaimana|bisa daftar|daftar di sini|daftar disini|langsung daftar|minta form|minta formulir|kirim form|kirim formulir|isi form|isi formulir|mau daftar|ingin daftar|pengen daftar|mau join|ingin join|pengen join|booking sekarang)/i;
  const asksInfo = /(apa saja|apa aja|harga|berapa|biaya|promo|free trial|trial|kelas|program|jadwal|jam|hari|kapan|lokasi|alamat|dimana|fasilitas|coach|special class)/i.test(msg) && !registrationPhrases.test(msg);

  const explicitJoinOnly =
    /(saya|aku|sy|aq)\s*(mau|ingin|pengen)\s*(daftar|join|booking|isi form)\b/i.test(msg) ||
    /^(daftar|join|booking|isi form|mau daftar|mau join)\b/i.test(msg) ||
    /(boleh|bisa)\s*(kirim|isi)\s*(form|formulir)/i.test(msg) ||
    registrationPhrases.test(msg);

  return (modelMarkedJoin || explicitJoinOnly) && explicitJoinOnly && !asksInfo;
}

function hasHallucinationSignals(text, mode) {
  if (!String(text || '').trim()) return true;
  if (/\bzumba\b/i.test(text)) return true;
  if (/\b(database|prompt|assistant|language model|chatgpt|openai)\b/i.test(text)) return true;
  if (/\[alamat lengkap gym\]/i.test(text)) return true;
  if (mode !== 'LOCATION' && /\b(jl\.|jalan\s+[a-z]|rt\s*\/\s*rw|kelurahan|kecamatan|blok\s+[a-z])\b/i.test(text)) return true;
  if (mode !== 'SOCIAL_MEDIA' && /\bdm instagram\b|hubungi admin resmi|whatsapp atau media sosial/i.test(text)) return true;
  return false;
}

function normalizeRupiahMentions(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/(\d+)\s*jt\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*juta\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*rb\b/g, (_, n) => String(Number(n) * 1000))
    .replace(/(\d+)\s*k\b/g, (_, n) => String(Number(n) * 1000))
    .replace(/(\d+)\s*ribu\b/g, (_, n) => String(Number(n) * 1000));
}

function extractMentionedPrices(text) {
  const normalized = normalizeRupiahMentions(text);
  return [...new Set((normalized.match(/\d{4,9}/g) || [])
    .map(value => Number(value))
    .filter(value => Number.isFinite(value) && value > 0))];
}

function rupiahNumber(value) {
  const numeric = Number(String(value || '').replace(/\D/g, ''));
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
}

function packageTokens(name) {
  return String(name || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(token => token.length >= 4 && !['days', 'challenge', 'program', 'paket', 'class', 'hari', 'fit'].includes(token));
}

function findMatchedPackages(userText, rows) {
  const msg = String(userText || '').toLowerCase();
  const mentionedPrices = extractMentionedPrices(msg);

  return rows
    .map(row => {
      const fullName = String(row.nama_paket || '').toLowerCase();
      if (!fullName) return { row, score: 0 };

      let score = 0;
      if (msg.includes(fullName)) score += 100;

      const rowPrice = rupiahNumber(row.harga);
      if (rowPrice && mentionedPrices.includes(rowPrice)) score += 80;

      const tokens = packageTokens(fullName);
      const matchedTokens = tokens.filter(token => msg.includes(token));
      score += matchedTokens.length * 10;
      if (tokens.length > 0 && matchedTokens.length === tokens.length) score += 25;

      if (/challenge/.test(msg) && /challenge/.test(fullName)) score += 8;
      if (/private/.test(msg) && /private/.test(fullName)) score += 8;
      if (/vip/.test(msg) && /vip/.test(fullName)) score += 8;
      if (/reguler/.test(msg) && /reguler/.test(fullName)) score += 8;

      return { row, score };
    })
    .filter(entry => entry.score > 0)
    .sort((a, b) => b.score - a.score || (rupiahNumber(a.row.harga) || 0) - (rupiahNumber(b.row.harga) || 0))
    .map(entry => entry.row);
}

function formatPackageDetail(row) {
  const harga = rupiahNumber(row.harga);
  const hargaStr = harga ? `Rp${harga.toLocaleString('id-ID')}` : (row.harga || '-');
  const lines = [];

  lines.push(`_*${row.nama_paket} (${hargaStr}, ${row.durasi || '-'})*_`);

  if (row.fasilitas_utama) {
    lines.push('*Fasilitas:*');
    row.fasilitas_utama
      .split(/[,;]/)
      .map(f => f.trim())
      .filter(Boolean)
      .forEach(f => lines.push(`· ${f}`));
  }

  if (row.ketentuan) {
    lines.push('');
    lines.push(`*Ketentuan:* ${row.ketentuan}`);
  }

  return lines.join('\n');
}

function formatPriceList(rows) {
  const lines = rows.map(r => {
    const harga = String(r.harga || '').trim() || '-';
    const durasi = String(r.durasi || '').trim() || '-';
    const numericHarga = Number(String(harga).replace(/\D/g, ''));
    const hargaText = Number.isFinite(numericHarga) && numericHarga > 0
      ? `Rp${numericHarga.toLocaleString('id-ID')}`
      : harga;
    return `- *${r.nama_paket}*: ${hargaText} (${durasi})`;
  });

  return [
    'Tentu kak 😊 Berikut kami kirim pricelist StepUp yang bisa kakak lihat terlebih dahulu ya:',
    '',
    ...lines,
    '',
    '*Disclaimer:* Setiap paket punya fasilitas dan ketentuan yang berbeda ya kak. Kalau ada paket yang mau ditanyakan lebih detail, nanti kami bantu jelaskan 🙂'
  ].join('\n');
}

function formatPackageComparison(rows) {
  const topRows = rows.slice(0, 2);
  const blocks = [];

  topRows.forEach(row => {
    const harga = rupiahNumber(row.harga);
    const hargaStr = harga ? `Rp${harga.toLocaleString('id-ID')}` : (row.harga || '-');
    const lines = [];

    lines.push(`*${row.nama_paket} (${hargaStr}, ${row.durasi || '-'})*`);

    if (row.fasilitas_utama) {
      lines.push('Fasilitas:');
      row.fasilitas_utama
        .split(/[,;]/)
        .map(f => f.trim())
        .filter(Boolean)
        .forEach(f => lines.push(`· ${f}`));
    }

    if (row.ketentuan) {
      lines.push('');
      lines.push(`*Ketentuan:* ${row.ketentuan}`);
    }

    blocks.push(lines.join('\n'));
  });

  return blocks.join('\n\n');
}

function getGreeting(text) {
  if (/assalamualaikum/i.test(text)) return 'Waalaikumsalam kak, ';
  if (/selamat pagi|pagi|morning/i.test(text)) return 'Pagi kak, ';
  if (/selamat siang|siang/i.test(text)) return 'Siang kak, ';
  if (/selamat sore|sore/i.test(text)) return 'Sore kak, ';
  if (/selamat malam|malam/i.test(text)) return 'Malam kak, ';
  if (/halo|hallo|hello|hi|hey|hai|hei/i.test(text)) return 'Hai kak, ';
  return '';
}

function startsWithGreeting(text) {
  return /^(waalaikumsalam|assalamualaikum|selamat pagi|selamat siang|selamat sore|selamat malam|pagi kak|siang kak|sore kak|malam kak|hai kak|halo kak|hello kak|hi kak|hai|halo|hello|hi)\b/i.test(String(text || '').trim());
}

const userText = String(ctx.userMessage || '').trim();
const hasGreetingPrefix = !!ctx.hasGreetingPrefix ||
  /^(halo|hallo|hello|hi|hey|hai|hei|assalamualaikum|selamat pagi|selamat siang|selamat sore|selamat malam)/i.test(userText);

const allHarga = $('Fetch Sheet Harga').all()
  .map(d => d.json)
  .filter(r => {
    const s = String(r.status || '').toLowerCase();
    return r && r.nama_paket && (!s || s === 'active' || s === 'aktif');
  });

const cleanBase = rawReply || fallbackReply;
let isJoin = classifyJoinIntent(ctx.userMessage, cleanBase);

const explicitRegistration =
  /^(daftar|join|mau daftar|mau join|pengen daftar|pengen join|ingin daftar|ingin join)\b/i.test(userText) ||
  /(boleh|bisa)\s*(kirim|isi)\s*(form|formulir)/i.test(userText) ||
  /(saya|aku|sy|aq)\s*(mau|ingin|pengen)\s*(daftar|join|booking)\b/i.test(userText);

if (explicitRegistration) {
  isJoin = true;
}

let cleanReply = humanClean(cleanBase)
  .replace(/\s*\[INTENT:JOIN\]\s*/g, '')
  .trim() || fallbackReply;

if (hasHallucinationSignals(cleanReply, answerMode)) {
  cleanReply = fallbackReply;
}

if (answerMode === 'PRICE_GENERAL_CLARIFY' && allHarga.length > 0) {
  cleanReply = formatPriceList(allHarga);
}

const matchedPackages = findMatchedPackages(userText, allHarga);
const matchedPackage = matchedPackages[0] || null;

if (
  matchedPackage &&
  /fasilitas|ketentuan|include|termasuk|dapat apa|dapet apa|apa aja/i.test(userText)
) {
  cleanReply = formatPackageDetail(matchedPackage);
}

if (
  matchedPackages.length >= 2 &&
  /apa bedanya|bedanya apa|beda apa|beda nya|perbedaannya|perbedaan|compare|bandingkan|vs\b|versus/i.test(userText)
) {
  cleanReply = formatPackageComparison(matchedPackages);
}

if (answerMode !== 'LOCATION') {
  cleanReply = cleanReply
    .split('\n')
    .filter(line => !/(\[alamat lengkap gym\]|\bjl\.\s|\bjalan\s+[a-z]|\brt\s*\/|\bkelurahan\b)/i.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim() || fallbackReply;
}

if (answerMode === 'SCHEDULE_SPECIFIC_DAY') {
  cleanReply = cleanReply
    .split('\n')
    .filter(line => !/mau dicekkan.*hari apa|cekkan.*hari apa/i.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim() || fallbackReply;
}

// Greeting final: jangan tambahkan sapaan ganda.
// Hanya tambahkan greeting jika mode memang GREETING dan reply belum punya sapaan.
if (answerMode === 'GREETING' && hasGreetingPrefix && cleanReply && !startsWithGreeting(cleanReply)) {
  const greeting = getGreeting(userText);
  if (greeting) {
    cleanReply = greeting + cleanReply.charAt(0).toLowerCase() + cleanReply.slice(1);
  }
}

// Jika user tidak menyapa dan ini bukan mode greeting, bersihkan sapaan pembuka yang tidak perlu.
if (!hasGreetingPrefix && answerMode !== 'GREETING') {
  cleanReply = cleanReply
    .replace(/^(selamat pagi|selamat siang|selamat sore|selamat malam|pagi kak|siang kak|sore kak|malam kak|hai kak|halo kak|hello kak|hi kak|hai|halo|hello|hi|assalamualaikum|waalaikumsalam)[!,.:\s-]*/i, '')
    .trim();
}

const charLength = cleanReply.length;
let delaySeconds;
if (charLength < 80) delaySeconds = 3;
else if (charLength < 200) delaySeconds = 4;
else if (charLength < 400) delaySeconds = 5;
else delaySeconds = 6;

return {
  json: {
    ...item,
    replyText: cleanReply,
    isJoin,
    joinIntentGuard: isJoin ? 'explicit_join' : 'info_or_unclear',
    hadError: !rawReply,
    errorMessage: rawReply ? '' : 'Model returned empty output',
    delaySeconds,
    chat_id: item.chat_id || ctx.chat_id,
    whatsapp_number: item.whatsapp_number || ctx.whatsapp_number,
    client_id: item.client_id || ctx.client_id,
    session_name: item.session_name || ctx.session_name || 'Tab',
    timestamp: item.timestamp || ctx.timestamp,
    lead_id: item.lead_id || ctx.lead_id
  }
};

