const stylist = $input.first().json || {};
const parsed = $('Parse LLM Result').first().json || {};
const ctx = $('Build Human WhatsApp Context').first().json || {};

const styledReplyRaw = String(
  stylist.output?.[0]?.content?.[0]?.text ||
  stylist.text ||
  stylist.message?.content ||
  stylist.response?.text ||
  stylist.replyText ||
  ''
).trim();

const parsedReply = String(parsed.replyText || '').trim();
const answerMode = String(ctx.answerMode || 'GENERAL');
const userMessage = String(ctx.userMessage || '').trim();

function cleanText(text) {
  return String(text || '')
    .replace(/\[INTENT:JOIN\]/g, '')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function hasDoubleGreeting(text) {
  const t = String(text || '').toLowerCase().trim();
  return (
    /^(pagi kak|siang kak|sore kak|malam kak),?\s*selamat (pagi|siang|sore|malam)/i.test(t) ||
    /^(hai kak|halo kak),?\s*selamat (pagi|siang|sore|malam)/i.test(t) ||
    /^(selamat (pagi|siang|sore|malam)),?\s*(pagi kak|siang kak|sore kak|malam kak)/i.test(t)
  );
}

function hasRobotCta(text) {
  return /kami\s+siap\s+membantu|jangan\s+ragu\s+untuk\s+(tanya|menghubungi)|feel\s+free\s+to|silakan\s+tanya/i.test(String(text || '').toLowerCase());
}

function hasHallucinationSignals(text, mode) {
  const t = String(text || '').toLowerCase();
  if (!t) return true;
  if (/\bzumba\b/i.test(t)) return true;
  if (/\b(database|prompt|assistant|language model|chatgpt|openai)\b/i.test(t)) return true;
  if (/\[alamat lengkap gym\]/i.test(t)) return true;
  if (mode !== 'LOCATION' && /\b(jl\.|jalan\s+[a-z]|rt\s*\/\s*rw|kelurahan|kecamatan|blok\s+[a-z])\b/i.test(t)) return true;
  return false;
}

function isTooDifferentFromParsed(baseText, styledText) {
  const base = cleanText(baseText).toLowerCase();
  const styled = cleanText(styledText).toLowerCase();

  if (!base || !styled) return false;

  const baseWords = base.split(/\s+/).filter(Boolean);
  const styledWords = styled.split(/\s+/).filter(Boolean);

  if (styledWords.length > baseWords.length * 2.2) return true;
  if (styledWords.length < Math.max(3, Math.floor(baseWords.length * 0.35))) return true;

  return false;
}

let finalReply = cleanText(styledReplyRaw);
let replyStatus = 'styled_ok';
let usedFallback = false;
let fallbackReason = '';

if (!finalReply) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'empty_stylist_output';
}

if (!usedFallback && hasDoubleGreeting(finalReply)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'double_greeting_detected';
}

if (!usedFallback && hasHallucinationSignals(finalReply, answerMode)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'hallucination_signal_detected';
}

if (!usedFallback && isTooDifferentFromParsed(parsedReply, finalReply)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'styled_reply_too_different';
}

if (!usedFallback && hasRobotCta(finalReply) && !hasRobotCta(parsedReply)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'robotic_cta_reintroduced';
}

finalReply = cleanText(finalReply);

return {
  json: {
    ...parsed,
    final_reply: finalReply,
    replyText: finalReply,
    reply_status: replyStatus,
    used_fallback: usedFallback,
    fallback_reason: fallbackReason,
    stylist_reply_raw: styledReplyRaw,
    answerMode,
    userMessage
  }
};

