  msg.raw_user_message ||
  msg.userMessage ||
  ''
).trim();

const userText = rawUserMessage.toLowerCase();

const needsConsultation = !!msg.needs_consultation;
const consultationTopic = String(msg.consultation_topic || '');
const consultationPriority = String(msg.consultation_priority || 'low');

const hasSensitiveCondition = !!msg.has_sensitive_condition;
const riskFlags = Array.isArray(msg.risk_flags) ? msg.risk_flags : [];
const safeModeRequired = !!msg.safe_mode_required;
const shouldBlockDirectRecommendation = !!msg.should_block_direct_recommendation;

const isAcknowledgement = !!msg.is_acknowledgement;
const isGreetingOnly = !!msg.is_greeting_only;
const isClassDetailIntent = !!msg.is_class_detail_intent;
const isLocationIntent = !!msg.is_location_intent;
const isAdminIntent = !!msg.is_admin_intent;
const isJoinIntent = !!msg.is_join_intent;
const microIntent = String(msg.micro_intent || 'general_info');

let canRecommendDirectly = true;
let recommendationMode = 'direct_answer_allowed';
let mustHandoffAdmin = false;
let mustHandoffCoach = false;
let consultationResponseType = 'normal_info';
let eligibilityReason = 'standard_info_safe';

if (isGreetingOnly || isAcknowledgement) {
  canRecommendDirectly = true;
  recommendationMode = 'light_response_only';
  consultationResponseType = 'light_response';
  eligibilityReason = 'greeting_or_acknowledgement';
} else if (isLocationIntent || isAdminIntent || isClassDetailIntent) {
  canRecommendDirectly = true;
  recommendationMode = 'direct_answer_allowed';
  consultationResponseType = 'direct_reference_answer';
  eligibilityReason = 'reference_question_safe';
} else if (isJoinIntent && !hasSensitiveCondition) {
  canRecommendDirectly = true;
  recommendationMode = 'direct_answer_allowed';
  consultationResponseType = 'join_guidance';
  eligibilityReason = 'join_intent_safe';
} else if (shouldBlockDirectRecommendation) {
  canRecommendDirectly = false;
  recommendationMode = 'handoff_required';
  mustHandoffAdmin = true;
  mustHandoffCoach = true;
  consultationResponseType = 'empathetic_handoff';
  eligibilityReason = 'sensitive_condition_blocks_recommendation';
} else if (hasSensitiveCondition || safeModeRequired) {
  canRecommendDirectly = false;
  recommendationMode = 'general_guidance_only';
  mustHandoffAdmin = true;
  consultationResponseType = 'careful_guidance';
  eligibilityReason = 'safe_mode_required';
} else if (needsConsultation && consultationPriority === 'high') {
  canRecommendDirectly = false;
  recommendationMode = 'general_guidance_only';
  mustHandoffAdmin = true;
  consultationResponseType = 'consultative_guidance';
  eligibilityReason = 'high_priority_consultation';
} else if (needsConsultation && consultationPriority === 'medium') {
  canRecommendDirectly = false;
  recommendationMode = 'general_guidance_only';
  consultationResponseType = 'consultative_guidance';
  eligibilityReason = 'medium_priority_consultation';
} else if (needsConsultation) {
  canRecommendDirectly = false;
  recommendationMode = 'general_guidance_only';
  consultationResponseType = 'light_consultative_guidance';
  eligibilityReason = 'consultation_detected';
}

if (
  consultationTopic === 'nutrition_product' &&
  (hasSensitiveCondition || riskFlags.includes('postpartum') || riskFlags.includes('c_section'))
) {
  canRecommendDirectly = false;
  recommendationMode = 'handoff_required';
  mustHandoffAdmin = true;
  mustHandoffCoach = true;
  consultationResponseType = 'nutrition_sensitive_handoff';
  eligibilityReason = 'nutrition_request_with_sensitive_condition';
}

if (
  consultationTopic === 'program_selection' &&
  needsConsultation &&
  !hasSensitiveCondition &&
  consultationPriority !== 'high'
) {
  canRecommendDirectly = false;
  recommendationMode = 'general_guidance_only';
  consultationResponseType = 'program_selection_guidance';
  eligibilityReason = 'program_selection_needs_guidance';
}

return {
  json: {
    ...msg,
    can_recommend_directly: canRecommendDirectly,
    recommendation_mode: recommendationMode,
    must_handoff_admin: mustHandoffAdmin,
    must_handoff_coach: mustHandoffCoach,
    consultation_response_type: consultationResponseType,
    eligibility_reason: eligibilityReason
  }
};

const assembled = $('Assemble Answer Facts').first().json || {};
const eligibility = $('Recommendation Eligibility Checker').first().json || {};
const consult = $('Consultation Need Detector').first().json || {};
const sensitive = $('Sensitive Condition').first().json || {};
const incoming = $('Normalize Incoming Message').first().json || {};

const userMessage = String(
  eligibility.raw_user_message ||
  consult.raw_user_message ||
  incoming.userMessage ||
  assembled.answer_facts?.userMessage ||
  ''
).trim();

const recommendationMode = String(eligibility.recommendation_mode || 'direct_answer_allowed');
const consultationResponseType = String(eligibility.consultation_response_type || 'normal_info');
const eligibilityReason = String(eligibility.eligibility_reason || '');
const mustHandoffAdmin = !!eligibility.must_handoff_admin;
const mustHandoffCoach = !!eligibility.must_handoff_coach;
const canRecommendDirectly = !!eligibility.can_recommend_directly;

const needsConsultation = !!consult.needs_consultation;
const consultationTopic = String(consult.consultation_topic || '');
const consultationPriority = String(consult.consultation_priority || 'low');

const hasSensitiveCondition = !!sensitive.has_sensitive_condition;
const riskFlags = Array.isArray(sensitive.risk_flags) ? sensitive.risk_flags : [];

const answerFacts = assembled.answer_facts || {};
const primaryFactType = String(assembled.primary_fact_type || 'general');
const primaryFactPayload = assembled.primary_fact_payload || null;
const fallbackFactPayload = assembled.fallback_fact_payload || {};

let shouldUseConsultativeStyle = false;
let consultativeReplyMode = 'normal_info';
let handoffReason = '';
let safeGuidanceText = '';
let adminHandoffText = '';
let consultativeFacts = {};

if (
  needsConsultation ||
  hasSensitiveCondition ||
  recommendationMode === 'general_guidance_only' ||
  recommendationMode === 'handoff_required'
) {
  shouldUseConsultativeStyle = true;
}

if (recommendationMode === 'handoff_required') {
  consultativeReplyMode = 'empathetic_handoff';
  handoffReason = eligibilityReason || 'sensitive_case_requires_handoff';
} else if (recommendationMode === 'general_guidance_only') {
  consultativeReplyMode = 'careful_guidance';
  handoffReason = eligibilityReason || 'consultative_case_needs_careful_guidance';
} else if (!canRecommendDirectly && needsConsultation) {
  consultativeReplyMode = 'consultative_guidance';
  handoffReason = eligibilityReason || 'consultative_support_needed';
}

if (consultativeReplyMode === 'empathetic_handoff') {
  safeGuidanceText =
    'Balas dengan empati, validasi kondisi user, jangan langsung arahkan ke paket atau pricelist, dan jelaskan bahwa kondisi seperti ini lebih aman dibantu melalui konsultasi admin atau coach terlebih dahulu.';
} else if (consultativeReplyMode === 'careful_guidance') {
  safeGuidanceText =
    'Balas dengan empati dan arahan umum yang aman. Jangan memberi rekomendasi agresif atau terlalu spesifik. Jika perlu, arahkan ke admin untuk konsultasi lanjutan.';
} else if (consultativeReplyMode === 'consultative_guidance') {
  safeGuidanceText =
    'Balas dengan gaya konsultatif: pahami kebutuhan user dulu, lalu beri arahan umum yang relevan tanpa terlalu cepat menjual paket.';
}

if (mustHandoffAdmin || mustHandoffCoach) {
  adminHandoffText =
    'Jika data atau kondisi user membutuhkan pendampingan lebih lanjut, arahkan dengan hangat ke admin atau coach untuk konsultasi lanjutan.';
}

consultativeFacts = {
  userMessage,
  needsConsultation,
  consultationTopic,
  consultationPriority,
  hasSensitiveCondition,
  riskFlags,
  recommendationMode,
  consultationResponseType,
  mustHandoffAdmin,
  mustHandoffCoach,
  primaryFactType,
  primaryFactPayload,
  fallbackFactPayload,
  safeGuidanceText,
  adminHandoffText
};

return {
  json: {
    ...assembled,
    should_use_consultative_style: shouldUseConsultativeStyle,
    consultative_reply_mode: consultativeReplyMode,
    consultative_facts: consultativeFacts,
    safe_guidance_text: safeGuidanceText,
    admin_handoff_text: adminHandoffText,
    handoff_reason: handoffReason
  }
};
